import { readFileSync } from 'node:fs';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { decodeDiagnostics, getDiagnosticsInfo, readDiagnostics, startDiagnostics, DiagnosticsTimeout } from '../src/upload-diagnostics';
import { queueBluetoothCall, resetBluetoothQueue } from '../src/bluetooth-queue';
import { analyzeDiagnostics, loadDiagnosticReport, saveDiagnosticReport } from '../tools/upload-stress-diagnostics';

// Generated by scripts/tests/test_ble_upload_diag.c in the firmware repository.
const fixture = new Uint8Array(readFileSync('tests/fixtures/ble-upload-diag-v1.bin'));
function fakeFirmware(pageSize = 100) {
  let op = 0, offset = 0;
  let snapshot = fixture.slice();
  const info = new Uint8Array(20), v = new DataView(info.buffer);
  v.setUint32(0,0x31474442,true); v.setUint32(4,123,true); v.setUint32(8,42,true); v.setUint32(12,1,true);
  v.setUint8(16,1); v.setUint8(17,2); v.setUint16(18,8416,true);
  return {
    info, snapshot,
    writeValueWithResponse: vi.fn(async (bytes: Uint8Array) => {
      const c = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength); op = bytes[0];
      if (op === 1) { v.setUint32(8,c.getUint32(1,true),true); v.setUint8(17,1); }
      if (op === 2) v.setUint8(17,2);
      if (op === 3) offset = c.getUint32(5,true);
    }),
    readValue: vi.fn(async () => {
      if (op !== 3) return new DataView(info.slice().buffer);
      const n = Math.min(pageSize, snapshot.length-offset), page = new Uint8Array(20+n), p = new DataView(page.buffer);
      p.setUint32(0,v.getUint32(4,true),true); p.setUint32(4,v.getUint32(8,true),true); p.setUint32(8,1,true);
      p.setUint32(12,offset,true); p.setUint32(16,8416,true); page.set(snapshot.subarray(offset,offset+n),20);
      return p;
    }),
  };
}
const characteristic = (fake: ReturnType<typeof fakeFirmware>) => fake as unknown as BluetoothRemoteGATTCharacteristic;
const expected = { bootId:123, runId:42, snapshotId:1, state:2, version:1, bytes:8416 };

describe('firmware diagnostic protocol', () => {
  beforeEach(resetBluetoothQueue);
  it('decodes the snapshot produced by the actual C recorder', () => {
    const capture = decodeDiagnostics(fixture);
    expect(capture).toMatchObject({bootId:123, runId:42, uploadCount:2, minMsysFree:0, disconnectReason:19});
    expect(capture.uploads[0]).toMatchObject({expectedLen:43000, expectedCrc:0x78b1cba3, gapStatus:14, confirmedUs:13005000});
    expect(capture.uploads[1]).toMatchObject({allocationOk:0, sendRc:6, confirmedUs:0});
    expect(capture.sensors[0].allocationFailures).toBe(2);
  });
  it.each([2,100,492])('retrieves complete pages with %i payload bytes', async (pageSize) => {
    const fake = fakeFirmware(pageSize);
    expect(await readDiagnostics(characteristic(fake),expected)).toEqual(decodeDiagnostics(fixture));
  });
  it('starts a capture with a clock bracket', async () => {
    const fake = fakeFirmware();
    const start = await startDiagnostics(characteristic(fake),77);
    expect(start.runId).toBe(77); expect(start.after).toBeGreaterThanOrEqual(start.before);
  });
  it('rejects wrong boots and run IDs before freezing', async () => {
    for (const mismatch of [{bootId:999},{runId:999}]) {
      const fake=fakeFirmware();
      await expect(readDiagnostics(characteristic(fake),{...expected,...mismatch})).rejects.toThrow();
      expect(fake.writeValueWithResponse.mock.calls.every(([c]) => c[0] !== 2)).toBe(true);
    }
  });
  it('rejects truncated capability, snapshot and pages', async () => {
    expect(() => decodeDiagnostics(fixture.subarray(1))).toThrow('Incomplete');
    const fake = fakeFirmware(); fake.readValue.mockResolvedValueOnce(new DataView(new ArrayBuffer(2)));
    await expect(getDiagnosticsInfo(characteristic(fake))).rejects.toThrow('malformed');
    const broken=fakeFirmware();
    const read=broken.readValue.getMockImplementation()!;
    let n=0; broken.readValue.mockImplementation(async () => ++n === 3 ? new DataView(new ArrayBuffer(20)) : read());
    await expect(readDiagnostics(characteristic(broken),expected)).rejects.toThrow('Truncated');
  });
  it('rejects mismatched page offsets', async () => {
    const fake=fakeFirmware(); const read=fake.readValue.getMockImplementation()!;
    fake.readValue.mockImplementation(async () => { const v=await read(); if(v.byteLength>20) v.setUint32(12,123,true); return v; });
    await expect(readDiagnostics(characteristic(fake),expected)).rejects.toThrow('mismatched');
  });
  it('does not release the queue after a native diagnostic operation stalls', async () => {
    vi.useFakeTimers();
    const fake=fakeFirmware(); fake.readValue.mockImplementation(() => new Promise(()=>{}));
    const request=getDiagnosticsInfo(characteristic(fake));
    const rejected=expect(request).rejects.toBeInstanceOf(DiagnosticsTimeout);
    await vi.advanceTimersByTimeAsync(30000); await rejected;
    const next=vi.fn(); const queued=queueBluetoothCall(async()=>next());
    const cancelled=expect(queued).rejects.toThrow('disconnected');
    await vi.advanceTimersByTimeAsync(100); expect(next).not.toHaveBeenCalled();
    resetBluetoothQueue(); await cancelled;
  });
});

describe('diagnostic analysis and persistence', () => {
  it('uses actual allocation evidence and does not treat a low watermark as proof', () => {
    const snapshot=decodeDiagnostics(fixture);
    const capture={status:'collected' as const, start:{...expected,before:0,after:100},snapshot};
    const attempts=snapshot.uploads.map(u=>({number:u.ordinal,size:u.expectedLen,expectedCrc:u.expectedCrc,outcome:'failed'}));
    expect(analyzeDiagnostics(attempts,capture)[1].classification).toBe('allocation-failed');
    snapshot.uploads[0].confirmedUs=0;
    expect(analyzeDiagnostics(attempts,capture)[0].classification).toBe('unconfirmed');
    snapshot.uploads[0].flags|=4;
    expect(analyzeDiagnostics(attempts,capture)[0].classification).toBe('inconclusive');
  });
  it('retains reports across reload and tolerates unavailable or corrupt storage', () => {
    const storage={setItem:vi.fn(),getItem:vi.fn()};
    expect(saveDiagnosticReport({schemaVersion:6},storage)).toBe(true);
    storage.getItem.mockReturnValue(storage.setItem.mock.calls[0][1]);
    expect(loadDiagnosticReport(storage)).toEqual({schemaVersion:6});
    storage.getItem.mockReturnValue('{'); expect(loadDiagnosticReport(storage)).toBeNull();
    storage.setItem.mockImplementation(()=>{throw new Error('quota');});
    expect(saveDiagnosticReport({},storage)).toBe(false);
  });
});
